{"file_path":"./src/lib.rs","content":"const BOOK_PRICE: u32 = 800;

fn group_price(size: usize) -> u32 {
    let discount = match size {
        0 => 0,
        1 => 0,
        2 => 5,
        3 => 10,
        4 => 20,
        5 => 25,
        _ => unreachable!("groups only ever contain up to 5 distinct books"),
    };
    size as u32 * BOOK_PRICE * (100 - discount) / 100
}

pub fn lowest_price(books: &[u32]) -> u32 {
    let mut counts = [0u32; 5];
    for &book in books {
        counts[(book - 1) as usize] += 1;
    }

    let mut groups = Vec::new();
    loop {
        let size = counts.iter().filter(|&&c| c > 0).count();
        if size == 0 {
            break;
        }
        for c in counts.iter_mut() {
            if *c > 0 {
                *c -= 1;
            }
        }
        groups.push(size);
    }

    // Replacing a group of 5 and a group of 3 with two groups of 4 is
    // always at least as cheap, so apply that swap wherever possible.
    let fives = groups.iter().filter(|&&s| s == 5).count();
    let threes = groups.iter().filter(|&&s| s == 3).count();
    let swaps = fives.min(threes);
    groups.retain(|&s| s != 5 && s != 3);
    for _ in 0..swaps {
        groups.push(4);
        groups.push(4);
    }
    for _ in 0..(fives - swaps) {
        groups.push(5);
    }
    for _ in 0..(threes - swaps) {
        groups.push(3);
    }

    groups.into_iter().map(group_price).sum()
}
"}

